    {topupOpen&&<div className="xp-modal-backdrop" onClick={()=>setTopupOpen(false)}><div className="xp-withdraw-modal xp-topup-modal" onClick={e=>e.stopPropagation()}><div className="xp-modal-head"><strong>Top up wallet</strong><button onClick={()=>setTopupOpen(false)}><X size={18}/></button></div>{!topupRequest?<><p>Wallet top-ups are ₹100–₹1,00,000. Funds are credited only after admin independently verifies the payment in the receiving account.</p><label>Top-up amount (INR)<input inputMode="decimal" value={topupAmount} onChange={e=>{if(e.target.value===""||/^\d{0,7}(\.\d{0,2})?$/.test(e.target.value))setTopupAmount(e.target.value)}} placeholder="Amount"/></label><div className="xp-info-note"><ShieldCheck size={17}/><span>{paymentConfig.instructions||"Pay only to the UPI destination configured by EasePay admin."}</span></div>{topupError&&<div className="xp-proof-error">{topupError}</div>}<button className="xp-primary" disabled={topupBusy||!paymentConfig.enabled||Number(topupAmount)<100||Number(topupAmount)>100000} onClick={async()=>{setTopupBusy(true);setTopupError("");try{const id="top_"+crypto.randomUUID().replace(/-/g,"").slice(0,24);const {data,error}=await supabase.rpc("create_wallet_topup_request",{p_id:id,p_amount_minor:Math.round(Number(topupAmount)*100)});if(error)throw error;setTopupRequest(data);}catch(e){setTopupError(e instanceof Error?e.message:"Could not create top-up request.");}finally{setTopupBusy(false)}}}>{topupBusy?"Creating…":"Continue to payment"}</button></>:<><div className="xp-topup-pay"><div className="xp-collect-amount">{money(Number(topupRequest.amount_minor)/100)}</div><strong>{topupRequest.beneficiary}</strong><span>{topupRequest.upi_id}</span><QRCodeSVG value={`upi://pay?pa=${encodeURIComponent(topupRequest.upi_id)}&pn=${encodeURIComponent(topupRequest.beneficiary)}&am=${Number(topupRequest.amount_minor)/100}&cu=INR&tn=${encodeURIComponent("EasePay wallet top-up "+topupRequest.id)}`} size={170} level="M" includeMargin bgColor="#ffffff" fgColor="#14283d"/><button className="xp-secondary" onClick={()=>{navigator.clipboard?.writeText(topupRequest.upi_id);showToast("UPI ID copied.");}}>Copy UPI ID</button><p>Pay the exact amount, then upload payment proof. This QR is not payment verification.</p></div><label>UTR / transaction reference<input value={topupUtr} onChange={e=>setTopupUtr(e.target.value.toUpperCase().replace(/[^A-Z0-9-]/g,""))} maxLength={35} placeholder="Enter UTR"/></label><label>Payment screenshot<input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>setTopupProof(e.target.files?.[0]||null)}/><small>JPG, PNG or WEBP · max 1 MB</small></label>{topupError&&<div className="xp-proof-error">{topupError}</div>}<button className="xp-primary" disabled={topupBusy||!topupProof||! /^[A-Z0-9-]{8,35}$/.test(topupUtr)} onClick={async()=>{setTopupBusy(true);setTopupError("");try{if(!topupProof||topupProof.size>1024*1024||!["image/jpeg","image/png","image/webp"].includes(topupProof.type))throw new Error("Upload JPG, PNG or WEBP under 1 MB.");const {data:{user}}=await supabase.auth.getUser();if(!user)throw new Error("Please sign in again.");const ext=topupProof.type==="image/jpeg"?"jpg":topupProof.type==="image/png"?"png":"webp";const path=user.id+"/"+topupRequest.id+"/proof-"+crypto.randomUUID()+"."+ext;const {error:uploadError}=await supabase.storage.from("xinpay-subscription-proofs").upload(path,topupProof,{contentType:topupProof.type,upsert:false});if(uploadError)throw uploadError;const {error}=await supabase.rpc("submit_wallet_topup_proof",{p_id:topupRequest.id,p_utr:topupUtr,p_proof_path:path});if(error)throw error;showToast("Top-up proof sent for review.");setTopupRequest({...topupRequest,status:"submitted"});await refreshWallet();}catch(e){setTopupError(e instanceof Error?e.message:"Proof submission failed.");}finally{setTopupBusy(false)}}}>{topupBusy?"Submitting…":"Submit top-up proof"}</button>{topupRequest.status==="submitted"&&<div className="xp-info-note"><ShieldCheck size={17}/><span>Proof submitted. Status: pending review. Balance will change after verified approval.</span></div>}</>}</div></div>}{activationPromptOpen&&<div className="xp-modal-backdrop" onClick={()=>setActivationPromptOpen(false)}><div className="xp-activation-modal" role="dialog" aria-modal="true" aria-labelledby="xp-activation-title" onClick={e=>e.stopPropagation()}><div className="xp-activation-icon"><ShieldCheck size={25}/></div><div className="xp-activation-copy"><h2 id="xp-activation-title">Activate account to withdraw</h2><p>Your account must be activated before withdrawal access is available. Complete the required account activation steps, then withdrawal access can be reviewed.</p></div><div className="xp-activation-actions"><button className="xp-secondary" onClick={()=>setActivationPromptOpen(false)}>Not now</button><button className="xp-primary" onClick={()=>{setActivationPromptOpen(false);go("Payments");}}>View activation steps</button></div></div></div>}{withdrawOpen&&<div className="xp-modal-backdrop" onClick={()=>setWithdrawOpen(false)}><div className="xp-withdraw-modal" onClick={e=>e.stopPropagation()}><div className="xp-modal-head"><strong>Withdraw funds</strong><button onClick={()=>setWithdrawOpen(false)}><X size={18}/></button></div><div className="xp-withdraw-balance"><span>Available balance</span><strong>{balanceVisible?(walletLoading?"…":money(availableMoney)):"••••••••"}</strong><small>Available for withdrawal</small></div><label>Withdrawal amount<input value={withdrawAmount} onChange={e=>{const v=e.target.value;if(v===""||/^\d{0,8}(\.\d{0,2})?$/.test(v))setWithdrawAmount(v)}} inputMode="decimal" placeholder="₹ 0.00"/></label><label>Withdrawal method<select value={withdrawMethod} onChange={e=>setWithdrawMethod(e.target.value)}><option>UPI</option><option>Bank transfer</option></select></label><label>{withdrawMethod==="UPI"?"UPI ID":"Bank account details"}<input value={withdrawDestination} onChange={e=>setWithdrawDestination(e.target.value)} placeholder={withdrawMethod==="UPI"?"name@upi":"Account number / IFSC and account name"}/></label><div className="xp-info-note"><ShieldCheck size={17}/><span>Minimum withdrawal ₹100. Requests reserve funds while pending. Payout is processed by admin.</span></div>{withdrawError&&<div className="xp-proof-error">{withdrawError}</div>}<button className="xp-primary" disabled={withdrawBusy||!withdrawAmount||Number(withdrawAmount)*100>Number(wallet?.available_minor||0)||Number(withdrawAmount)<100||!withdrawDestination.trim()} onClick={async()=>{setWithdrawError("");setWithdrawBusy(true);try{const amountMinor=Math.round(Number(withdrawAmount)*100);const id="wd_"+crypto.randomUUID().replace(/-/g,"").slice(0,24);const {error}=await supabase.rpc("customer_request_withdrawal",{p_id:id,p_amount_minor:amountMinor,p_method:withdrawMethod==="UPI"?"UPI":"BANK",p_destination:withdrawDestination.trim()});if(error)throw error;setWithdrawOpen(false);setWithdrawAmount("");setWithdrawDestination("");showToast("Withdrawal request submitted.");await refreshWallet();}catch(e){setWithdrawError(e instanceof Error?e.message:"Withdrawal request failed.");}finally{setWithdrawBusy(false)}}}>{withdrawBusy?"Submitting…":"Request withdrawal"}</button></div></div>}{toast&&<div className="xp-toast">{toast}</div>}
