function ReferralPanel({info,loading,url,refresh,toast}:{info:any;loading:boolean;url:string;refresh:()=>void;toast:(m:string)=>void}){
  const referrals=info.referrals||[];
  return (
    <>
      <PageHeading title="Refer & earn" subtitle="Share your admin-assigned referral link. Referral activity is tracked automatically."/>
      <section className="xp-panel xp-referral-panel">
        <div className="xp-referral-hero">
          <span className="xp-referral-icon"><Gift size={22}/></span>
          <div><h2>Your referral link</h2><p>Share this unique link with friends. Their registration will be attributed to your account.</p></div>
        </div>
        <div className="xp-referral-link-box">
          <span>{url}</span>
          <button className="xp-primary" onClick={async()=>{try{await navigator.clipboard.writeText(url);toast("Referral link copied.");}catch{toast("Could not copy link.");}}}><Copy size={16}/> Copy link</button>
        </div>
        <div className="xp-referral-stats">
          <div><Users size={18}/><small>Total referrals</small><strong>{loading?"…":Number(info.total_referrals||0)}</strong></div>
          <div><ShieldCheck size={18}/><small>Qualified</small><strong>{loading?"…":Number(info.qualified_referrals||0)}</strong></div>
          <div><Gift size={18}/><small>Rewards earned</small><strong>{loading?"…":money(Number(info.rewards_minor||0)/100)}</strong></div>
        </div>
        <div className="xp-panel-heading">
          <div><h3>Referral activity</h3><p>Recent signups attributed to your link.</p></div>
          <button className="xp-text-button" onClick={refresh}>Refresh</button>
        </div>
        {loading ? <div className="xp-empty">Loading referrals…</div> : referrals.length===0 ? <div className="xp-empty">No referrals yet. Share your link to get started.</div> : (
          <div className="xp-transaction-list">
            {referrals.map((r:any)=>(
              <div className="xp-transaction-row" key={r.id}>
                <div className="xp-transaction-symbol"><Users size={17}/></div>
                <div className="xp-transaction-info"><strong>Referral signup</strong><small>{new Date(r.created_at).toLocaleString("en-IN")}</small></div>
                <div className="xp-transaction-value"><strong>{money(Number(r.reward_minor||0)/100)}</strong><small className={"xp-status "+String(r.status).toLowerCase()}>{r.status}</small></div>
              </div>
            ))}
          </div>
        )}
      </section>
    </>
  );
}
function CustomerAuth(){
 const [mode,setMode]=useState<"signin"|"signup">(window.location.pathname==="/signup"?"signup":"signin");
 const [showPassword,setShowPassword]=useState(false);
 useEffect(()=>{let alive=true;supabase.auth.getSession().then(({data})=>{if(alive&&data.session)window.location.replace("/customer")});const {data:{subscription}}=supabase.auth.onAuthStateChange((event,session)=>{if(session&&(event==="SIGNED_IN"||event==="TOKEN_REFRESHED"))window.location.replace("/customer");});const onPop=()=>setMode(window.location.pathname==="/signup"?"signup":"signin");window.addEventListener("popstate",onPop);return()=>{alive=false;subscription.unsubscribe();window.removeEventListener("popstate",onPop)};},[]);
 const [fullName,setFullName]=useState("");
 const [email,setEmail]=useState("");
 const [password,setPassword]=useState("");
 const [busy,setBusy]=useState(false);
 const [message,setMessage]=useState("");
 const [messageTone,setMessageTone]=useState<"error"|"success">("error");
 function switchMode(next:"signin"|"signup"){
  setMode(next);setMessage("");setFullName("");setPassword("");setShowPassword(false);
  const referral=new URLSearchParams(window.location.search).get("ref");
  const url=next==="signup"?(referral?"/signup?ref="+encodeURIComponent(referral):"/signup"):"/login";
  window.history.pushState({}, "", url);
 }
 async function submit(e:React.FormEvent){
  e.preventDefault();setBusy(true);setMessage("");
  try{
   if(mode==="signup"){
    const {data,error}=await supabase.auth.signUp({email:email.trim(),password,options:{emailRedirectTo:window.location.origin+"/customer",data:{full_name:fullName.trim(),name:fullName.trim(),referral_code:(new URLSearchParams(window.location.search).get("ref")||"").trim().toUpperCase()}}});
    if(error)throw error;
    if(!data.session){
     setMessageTone("success");setMessage("Account created. Check your email to confirm your address, then sign in.");
     switchMode("signin");setMessageTone("success");setMessage("Account created. Check your email to confirm your address, then sign in.");
     return;
    }
    window.location.replace("/customer");return;
   }
   const {data,error}=await supabase.auth.signInWithPassword({email:email.trim(),password});
   if(error)throw error;
   if(!data.session)throw new Error("Sign-in did not create a session. Please try again.");
   window.location.replace("/customer");
  }catch(err){setMessageTone("error");setMessage(err instanceof Error?err.message:"Authentication failed.");}
  finally{setBusy(false);}
 }
 return <div className="xp-auth-wrap"><div className="xp-auth-layout"><aside className="xp-auth-aside"><a className="xp-auth-home" href="/" aria-label="Return to EasePay home"><EasePayLogo inverse /></a><div className="xp-auth-aside-copy"><span className="xp-auth-aside-label">PAYMENTS MADE CLEAR</span><h2>Everything you need.<br/><em>Nothing you don't.</em></h2><p>One secure place to manage your account, payment requests and activity.</p><div className="xp-auth-benefits"><span><ShieldCheck size={17}/> Secure account access</span><span><Activity size={17}/> Clear payment activity</span></div></div><div className="xp-auth-aside-bottom">EASEPAY <span>·</span> SIMPLE. SECURE. CLEAR.</div></aside><form className="xp-auth-card" onSubmit={submit}>
  <div className="xp-auth-card-top"><span className="xp-auth-kicker">CUSTOMER PORTAL</span><span className="xp-auth-secure-chip"><ShieldCheck size={14}/> Secure sign-in</span></div>
  <h1>{mode==="signin"?"Welcome back":"Create your account"}</h1>
  <p>{mode==="signin"?"Sign in to pick up where you left off.":"Set up your account to continue to payment setup and your dashboard."}</p>
  {mode==="signup"&&<label className="xp-auth-field"><span>Full name</span><input type="text" value={fullName} onChange={e=>setFullName(e.target.value)} required minLength={2} maxLength={80} autoComplete="name" placeholder="Your full name"/></label>}
  <label className="xp-auth-field"><span>Email address</span><input type="email" value={email} onChange={e=>setEmail(e.target.value)} required autoComplete="email" placeholder="you@example.com"/></label>
  <label className="xp-auth-field"><span>Password</span><div className="xp-password-wrap"><input type={showPassword?"text":"password"} value={password} onChange={e=>setPassword(e.target.value)} required minLength={6} autoComplete={mode==="signin"?"current-password":"new-password"} placeholder="At least 6 characters"/><button type="button" className="xp-password-toggle" onClick={()=>setShowPassword(v=>!v)} aria-label={showPassword?"Hide password":"Show password"}>{showPassword?<EyeOff size={18}/>:<Eye size={18}/>}</button></div></label>
  <button className="xp-primary xp-auth-submit" disabled={busy}>{busy?<><span className="xp-auth-spinner"/>Please wait…</>:mode==="signin"?"Sign in":"Create account"}<span className="xp-auth-arrow">→</span></button>
  {message&&<div className={messageTone==="success"?"xp-auth-message success":"xp-proof-error"} role="status">{message}</div>}
  <div className="xp-auth-switch">{mode==="signin"?"New to EasePay?":"Already registered?"}<button type="button" onClick={()=>switchMode(mode==="signin"?"signup":"signin")}>{mode==="signin"?"Create account":"Sign in"}</button></div>
  <div className="xp-auth-foot"><ShieldCheck size={16}/> Your credentials are encrypted and protected <a href="/">Back to home</a></div>
 </form></div></div>
}
function CustomerSetup({name,setName,busy,error,submit}:{name:string;setName:(v:string)=>void;busy:boolean;error:string;submit:(e:any)=>void}){return <div className="xp-auth-wrap"><form className="xp-auth-card xp-setup-card" onSubmit={submit}><div className="xp-brand"><EasePayLogo inverse /></div><div className="xp-auth-kicker">ACCOUNT SETUP · 1 OF 1</div><h1>Complete your profile</h1><p>Tell us what name to use on your customer account and payment records.</p><label>Full name<input value={name} onChange={e=>setName(e.target.value)} required minLength={2} maxLength={80} autoComplete="name" placeholder="Your full name"/></label><button className="xp-primary" disabled={busy||name.trim().length<2}>{busy?"Saving…":"Continue to dashboard"}</button>{error&&<div className="xp-proof-error">{error}</div>}<div className="xp-auth-foot"><ShieldCheck size={15}/> Secure account access</div></form></div>}
function PageHeading({title,subtitle}:{title:string;subtitle:string}){return <div className="xp-page-heading"><div><h1>{title}</h1><p className="xp-subtitle">{subtitle}</p></div></div>}
function TransactionList({items,onSelect}:{items:Tx[];onSelect:(tx:Tx)=>void}){return <div className="xp-transaction-list">{items.map(t=><button className="xp-transaction-row" key={t.id} onClick={()=>onSelect(t)}><div className="xp-transaction-symbol">{t.icon}</div><div className="xp-transaction-info"><strong>{t.name}</strong><small>{t.detail} <span>·</span> {t.date}</small></div><div className="xp-transaction-value"><strong className={t.kind==="Credit"?"credit":""}>{t.kind==="Credit"?"+":"−"}{money(t.amount)}</strong><small className={"xp-status "+t.status.toLowerCase()}>{t.status}</small></div><ChevronRight className="xp-row-chevron" size={16}/></button>)}</div>}


function TelegramPhoneVerification(){
 const [phone,setPhone]=useState("");const [verificationId,setVerificationId]=useState("");const [telegramUrl,setTelegramUrl]=useState("");const [status,setStatus]=useState<"idle"|"pending_link"|"linked"|"otp_sent"|"verified"|"expired"|"failed">("idle");const [otp,setOtp]=useState("");const [busy,setBusy]=useState(false);const [error,setError]=useState("");const [verifiedPhone,setVerifiedPhone]=useState("");
 useEffect(()=>{let alive=true;(async()=>{try{const r=await fetch("/api/telegram/verification/phone",{headers:await tgHeaders(),cache:"no-store"});const d=await r.json();if(alive&&r.ok&&d.verified){setStatus("verified");setPhone(d.phone||"");setVerifiedPhone(d.phone||"");}}catch{}})();return()=>{alive=false}},[]);
 useEffect(()=>{if(!verificationId||!["pending_link","linked","otp_sent"].includes(status))return;let stop=false;const poll=async()=>{try{const d=await getTelegramVerificationStatus(verificationId);if(!stop){setStatus(d.status);if(d.phone)setVerifiedPhone(d.phone)}}catch{}};poll();const t=window.setInterval(poll,3500);return()=>{stop=true;window.clearInterval(t)}},[verificationId,status]);
 async function begin(){setBusy(true);setError("");try{const d=await startTelegramVerification(phone);setVerificationId(d.verificationId);setTelegramUrl(d.telegramUrl);setStatus("pending_link");setOtp("");}catch(e){setError(e instanceof Error?e.message:"Could not start verification");}finally{setBusy(false)}}
 async function submit(){setBusy(true);setError("");try{const d=await verifyTelegramOtp(verificationId,otp);setStatus("verified");setVerifiedPhone(d.phone);}catch(e){setError(e instanceof Error?e.message:"OTP verification failed");}finally{setBusy(false)}}
 return <div className="xp-telegram-verification"><h3>Phone verification</h3><p>Connect Telegram, share your own phone contact with the bot, and enter the OTP. Telegram messaging is free.</p>{status==="verified"?<div className="xp-telegram-status success">Verified: {verifiedPhone||phone}</div>:<><label>Phone number<input value={phone} onChange={e=>setPhone(e.target.value)} placeholder="+91 98765 43210" type="tel" autoComplete="tel" disabled={status==="otp_sent"}/></label>{["idle","expired","failed"].includes(status)?<button className="xp-primary" disabled={busy||phone.trim().length<8} onClick={begin}>{busy?"Starting…":"Connect Telegram and send OTP"}</button>:null}{status==="pending_link"?<div className="xp-telegram-status">Open the bot, press Start, and share your own contact.<div className="xp-telegram-actions"><a className="xp-secondary" href={telegramUrl} target="_blank" rel="noopener noreferrer">Open Telegram bot</a><button className="xp-secondary" onClick={()=>{setStatus("idle");setVerificationId("");setTelegramUrl("");}}>Cancel</button></div></div>:null}{status==="linked"?<div className="xp-telegram-status">Telegram connected. Share your phone contact in the bot chat. Waiting for OTP…<a className="xp-secondary" href={telegramUrl} target="_blank" rel="noopener noreferrer">Return to Telegram</a></div>:null}{status==="otp_sent"?<><div className="xp-telegram-status">OTP sent to your linked Telegram chat. It expires in 5 minutes.</div><label>6-digit OTP<input inputMode="numeric" autoComplete="one-time-code" maxLength={6} value={otp} onChange={e=>setOtp(e.target.value.replace(/\D/g,"").slice(0,6))} placeholder="Enter OTP"/></label><button className="xp-primary" disabled={busy||otp.length!==6} onClick={submit}>{busy?"Verifying…":"Verify OTP"}</button></>:null}{error?<div className="xp-telegram-status error" role="alert">{error}</div>:null}</>}</div>;
}
